use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fmt::Write,fs,io::Read,path::Path};
const R:&str="/tmp/zopro-single-epoch-advancer";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-single-epoch-advancer";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn n(v:&Value)->f64{v.as_f64().unwrap()}
fn archive(root:&Path,dir:&Path,out:&Path,index:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().into_owned();let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();if e.file_type().unwrap().is_dir(){if !name.starts_with("target"){archive(root,&p,out,index)}continue}if s.starts_with("candidate/")&&!s.starts_with("candidate/.xtask/")&&!s.ends_with("Cargo.toml")&&!s.ends_with("Cargo.lock")&&!s.ends_with("src/internal.rs")&&!s.ends_with("src/advance_gate.rs"){continue}if !["rs","md","json","jsonl","log","txt","proof","public","toml","lock"].contains(&p.extension().and_then(|v|v.to_str()).unwrap_or(""))&&!name.starts_with("LICENSE"){continue}let dest=out.join(rel);fs::create_dir_all(dest.parent().unwrap()).unwrap();fs::copy(&p,&dest).unwrap();assert_eq!(hash(&p),hash(&dest));assert!(index.insert(s,hash(dest)).is_none());}}
fn main(){let r=Path::new(R);let d=Path::new(D);let a=read(r.join("analysis.json"));assert_eq!(a["SDK_requests"],19254);assert_eq!(a["independent_exports"],294);assert_eq!(a["next_prior_count"],12467);let p=read(r.join("performance/protocol.json"));for(f,h)in p["pins"].as_object().unwrap(){assert_eq!(hash(f),h.as_str().unwrap());}for(f,h)in read("/tmp/zopro-clean-fft-adoption/production-source-manifest.json")["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(f)),h.as_str().unwrap());}for(f,h)in read(r.join("proof-inventory.json")).as_object().unwrap(){assert_eq!(hash(f),h.as_str().unwrap());}
 let passed=a["full_gate_passed"].as_bool().unwrap();let mut md=format!("# One nonblocking epoch-advancement scanner\n\nFrozen speed screen: **{}**. Production and the accepted SDK remain unchanged; no adoption occurs in this report. The original all-eight CPU10× goal remains active and unmet.\n\nThe private Crossbeam-epoch0.9.21 candidate allows one participant-list advancement scanner per collector. A contending caller returns an observed epoch without waiting or scanning, and can still collect already expired bags. The original scan, epoch store, queue operations, pin frequency and collection expiration checks remain. Failed permit acquisition retains the original epoch-load ordering and SeqCst fence. A scoped permit releases on every exit and before the normal deferred-destructor loop. Explicit `ZOPRO_CPU_SINGLE_EPOCH_ADVANCER=1`, read at collector construction, enables the mode; OFF/default and no-std use the baseline path. One padded flag and immutable policy add fixed collector metadata; there are no key tables or proof buffers.\n\nThis targets redundant concurrent collector scans, separately from prior empty-victim, guard batching, collection-interval, retained-buffer and bounded-victim-search trials. Their failed or partial results remain. The [current-source C7a profile](../2026-10-27-pmu-c7a-aeglos/README.md) motivates the hypothesis but is not a measurement of this candidate. No fresh AWS or Aeglos comparison occurs here.\n\n## Complete SDK latency\n\nRyzen9950X, nine fixed rotated/reversed fresh-process blocks. Accepted uses the exact retained172-source SDK; OFF/ON share the new executable. All nine shapes use32workers onCPUs0–31, plus primary16 pinned toCPUs0–15, one logical CPU per physical core. Primary32 has151 measured calls after3primes, primary16 has251, others31. Loading/primes are excluded; fresh solving, randomness, proving, verification and serialization are timed. No owned build/helper/hash/archive or second benchmark overlaps SDK/profile requests.\n\nTimes are medians of process medians. Ratios pair corresponding blocks and need not equal ratios of displayed medians.\n\n|Case|Accepted ms|OFF ms|ON ms|ON/accepted paired|ON/OFF paired|\n|---|---:|---:|---:|---:|---:|\n",if passed{"pass"}else{"fail"});
 let cases=a["cases"].as_object().unwrap();for name in ["1x2-w32","2x2-w32","4x2-w32","8x2-w32","12x2-w32","16x2-w32","24x2-w32","merge-24x1-w32","merge-54x1-w32","1x2-w16"]{let c=&cases[name];writeln!(md,"|{name}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|",n(&c["modes"]["accepted"]["ms"]),n(&c["modes"]["off"]["ms"]),n(&c["modes"]["on"]["ms"]),n(&c["pairs"]["on/accepted"]["median_ratio"]),n(&c["pairs"]["on/off"]["median_ratio"])).unwrap();}
 write!(md,"\nThe declared gate uses individual distribution-free median intervals with endpoints2..8 over nine blocks (96.09375% nominal coverage under independent/exchangeable blocks; no familywise guarantee). Calibration intervals must lie wholly within factor1.03 for OFF/accepted in all10cases; ON nonregression upper bounds must be≤1.02 against both controls in everycase; primary32 strict gain upper bounds must be<1, and original-eight block-geometric aggregate upper bounds≤1. No minimum gain floor, exclusions, extensions or failed-bound waiver. Failed checks: calibration **{}**, nonregression **{}**, primary gain **{}**, aggregate **{}**. Positive estimates and uncertainty remain in [analysis](artifacts/analysis.json).\n",a["calibration_failures"].as_array().unwrap().len(),a["regressions"].as_array().unwrap().len(),a["primary_gain_failures"].as_array().unwrap().len(),a["aggregate_failures"].as_array().unwrap().len()).unwrap();
 md.push_str("\n## CPU work and memory\n\nCPU is median summed user+system time per timed request; RSS is maximum whole-process high water across ordinary latency processes, including load/primes. Neither isolates useful arithmetic or minimum RAM.\n\n|Case|Mode|CPU ms/request|Peak RSS MiB|\n|---|---|---:|---:|\n");for name in ["1x2-w32","1x2-w16","merge-54x1-w32"]{for mode in ["accepted","off","on"]{let c=&cases[name]["modes"][mode];writeln!(md,"|{name}|{mode}|{:.3}|{:.2}|",n(&c["cpu_ms_per_request"]),n(&c["maxrss_mib"])).unwrap();}}
 md.push_str("\n## Separate warm profiles\n\nSix199Hz user-cycle profiles follow all latency: primary32 uses251 measured calls after3primes, merge54 uses17. Zero lost records and one sampledSDKPID are checked. Flat shares have symbol/inlining limits and are not removable wall time or causal synchronization savings.\n\n|Case|Mode|Samples|Epoch %|Scheduler %|\n|---|---|---:|---:|---:|\n");let rows=read(r.join("performance/rows.json"));let mut raw=BTreeMap::new();for row in rows.as_array().unwrap().iter().filter(|v|v["phase"]=="profile"){let pct=|s:&str|row["profile"]["category_percent"][s].as_f64().unwrap_or(0.);writeln!(md,"|{}|{}|{}|{:.2}|{:.2}|",row["case"].as_str().unwrap(),row["variant"].as_str().unwrap(),row["profile"]["samples"],pct("epoch"),pct("scheduler")).unwrap();}
 fn raw_hashes(dir:&Path,out:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){raw_hashes(&e.path(),out)}else if e.file_name()=="perf.data"{out.insert(e.path().display().to_string(),hash(e.path()));}}}raw_hashes(&r.join("performance"),&mut raw);assert_eq!(raw.len(),6);save(r.join("raw-local-only-sha256.json"),&json!(raw));
 md.push_str("\n## Supplied M5 references\n\nHistorical supplied figures, not fresh matched-machine M5 measurements. Merge54 has no supplied reference.\n\n|Shape|CPU reference ms|Metal reference ms|ON ms|CPU/ON|Metal/ON|\n|---|---:|---:|---:|---:|---:|\n");for name in ["1x2-w32","2x2-w32","4x2-w32","8x2-w32","12x2-w32","16x2-w32","24x2-w32","merge-24x1-w32"]{let c=&cases[name];let ms=n(&c["modes"]["on"]["ms"]);let cpu=n(&c["reference"]["cpu_ms"]);let metal=n(&c["reference"]["metal_ms"]);writeln!(md,"|{}|{cpu:.0}|{metal:.0}|{ms:.6}|{:.3}×|{:.3}×|",c["shape"].as_str().unwrap(),cpu/ms,metal/ms).unwrap();}
 md.push_str("\n## Validation and limits\n\nThe candidate preserves the original advancement body byte-for-byte after removing inserted gate code. Root runtime dependency versions/edges are retained; only epoch uses a private path. Actual eight directly linked and four transitive scheduler/collector libraries are pinned. The first epoch suite passed43tests and failed one new test because its setup overlooked the first pin's automatic collection. The [test-only repair](artifacts/test-repair.json) acquires the test permit before pinning; that targeted test then passes, covering44tests across two invocations without repeating43successful checks. Added checks cover nonblocking contention/unwind release, skipped advancement, pinned-reader retention/release, and8192concurrent deferred callbacks reclaimed exactly once. Alloc/no-std check,119native core,2raw and6cubic tests pass with modeON. Field source is unchanged; inherited33field qualification is not a new run. These native tests do not prove the full memory model, fairness, bounded retention with stalled threads, mobile behavior or a universal progress bound.\n\nAll nine OFF/ON four-worker preflights complete72SDKcalls and18exports. Latency/profiles add19182calls and276exports: **19254SDKcalls,294distinct independently Gnark-verified exports,588proof/public members**. Exports are164bytes, public-fixture-bound and fresh against12173prior/newidentities. Ledger **12173→12467**. No successful SDK capture or verifier is repeated for repairs. No portable whole-prover, concurrent SDK, pressure,250/4999, phone,TEE, or new AWS qualification occurs. A passing speed screen would still require resource/compatibility review before promotion.\n\n[Declaration](artifacts/design.md), [source audit](artifacts/source-audit.json), [raw rows](artifacts/performance/rows.json), [proof inventory](artifacts/proof-inventory.json), [build qualification](artifacts/native-qualified/result.json), [artifact hashes](artifact-index.json). Rawperf.data and binaries/compiler caches remain local with hashes. Production remains unchanged.\n");
 save(r.join("closeout.json"),&json!({"status":"complete","full_gate_passed":passed,"SDK_requests":19254,"independent_exports":294,"next_prior_count":12467,"source_changed":false,"adopted":false,"goal_achieved":false,"owned_live_jobs":[],"owned_cloud_resources":[]}));fs::create_dir_all(d.join("artifacts")).unwrap();fs::write(d.join("README.md"),md).unwrap();let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);save(d.join("artifact-index.json"),&json!(index));for(f,h)in &index{assert_eq!(&hash(d.join("artifacts").join(f)),h);}println!("Closed single-advancer fullgate{passed};{}verified archive hashes;ledger12467",index.len());
}
